#!/bin/zsh
# Builds “RSS Feed Magazine.app” (Release, Apple Silicon) into build/; with --install also copies it to ~/Applications and launches it,
# with --zip also creates build/RSS-Feed-Magazine-<version>.zip for a GitHub release.
#
# Signing comes from xcconfig/common/NetNewsWire_codesigning_common.xcconfig (Developer ID, manual, no profiles).
# Not notarized, like Ulf’s other apps.
set -euo pipefail
cd "${0:A:h}/.."

# SecretKey.swift is generated by a build phase, but the Account package can compile before it exists.
./buildscripts/updateSecrets.sh >/dev/null

DERIVED=build/DerivedData
PRODUCT="$DERIVED/Build/Products/Release/RSS Feed Magazine.app"
rm -rf "$PRODUCT" # So a failed build can’t ship the previous one
xcodebuild -project NetNewsWire.xcodeproj -scheme NetNewsWire -configuration Release \
	-destination "platform=macOS,arch=arm64" -derivedDataPath "$DERIVED" build | grep -E "^[^ ].*(error|warning): |\*\* BUILD" | grep -v appintents || true

[[ -d "$PRODUCT" ]] || { echo "Build failed"; exit 1; }

APP="build/RSS Feed Magazine.app"
rm -rf "$APP"
ditto "$PRODUCT" "$APP"
codesign --verify --deep --strict "$APP"
VERSION=$(/usr/libexec/PlistBuddy -c "Print CFBundleShortVersionString" "$APP/Contents/Info.plist")
echo "Built: $APP ($VERSION)"

if [[ "${1:-}" == "--zip" ]]; then
	ZIP="build/RSS-Feed-Magazine-$VERSION.zip"
	rm -f "$ZIP"
	ditto -c -k --keepParent "$APP" "$ZIP"
	echo "Archive: $ZIP"
fi

if [[ "${1:-}" == "--install" ]]; then
	pkill -x "RSS Feed Magazine" || true
	mkdir -p ~/Applications
	rm -rf ~/"Applications/RSS Feed Magazine.app"
	ditto "$APP" ~/"Applications/RSS Feed Magazine.app"
	open ~/"Applications/RSS Feed Magazine.app"
	echo "Installed: ~/Applications/RSS Feed Magazine.app"
fi
